  --shadow-pop-sm: 0 4px 0 0 rgb(27 42 92 / 0.18);
  --shadow-soft: 0 10px 30px -10px rgb(27 42 92 / 0.25);

  --animate-float: float 4s ease-in-out infinite;
  --animate-wiggle: wiggle 2.4s ease-in-out infinite;
  --animate-pop-in: pop-in 0.35s cubic-bezier(0.34, 1.56, 0.64, 1) both;
  --animate-bounce-soft: bounce-soft 0.6s ease;
  --animate-shake: shake 0.4s ease;
  --animate-confetti: confetti-fall 1.6s ease-in forwards;

  @keyframes float {
    0%,
    100% {
      transform: translateY(0);
    }
    50% {
      transform: translateY(-12px);
    }
  }
  @keyframes wiggle {
    0%,
    100% {
      transform: rotate(-3deg);
    }
    50% {
      transform: rotate(3deg);
    }
  }
  @keyframes pop-in {
