        </div>
      </main>
    </div>
  );
}

"use client";
import type { Board, GridBoard, SortBoard, Block, RunResult, GridFrame, SortFrame, Pos } from "@/lib/missions/types";
import { useEffect, useState, useRef } from "react";
import { runMission } from "@/lib/missions/engine";

interface Props {
  board: Board;
  program: Block[];
  onResult: (res: RunResult) => void;
}

export function MissionBoard({ board, program, onResult }: Props) {
  const [isPlaying, setIsPlaying] = useState(false);
  const [frameIdx, setFrameIdx] = useState(0);
  const [frames, setFrames] = useState<any[]>([]); // GridFrame[] or SortFrame[]

  useEffect(() => {
    if (isPlaying && frameIdx < frames.length - 1) {
      const timer = setTimeout(() => setFrameIdx(i => i + 1), 600);
      return () => clearTimeout(timer);
    } else if (isPlaying && frameIdx >= frames.length - 1) {
      setIsPlaying(false);
      // Wait for last animation to finish, then report result
      setTimeout(() => {
        onResult(runMission({ board, palette: [], solution: [], hints: ["","",""], id: "", level: 1, order: 1, title: "", subject: "Logika", story: "", goal: "", optimalBlocks: 1 }, program));
      }, 500);
    }
  }, [isPlaying, frameIdx, frames, board, program, onResult]);

  const handlePlay = () => {
    // Generate frames
    const dummyMission = { board, palette: [], solution: [], hints: ["","",""], id: "", level: 1, order: 1, title: "", subject: "Logika", story: "", goal: "", optimalBlocks: 1 } as any;
    const res = runMission(dummyMission, program);
    if (res.reason === "empty") {
      onResult(res);
      return;
    }
    setFrames(board.kind === "grid" ? (res.gridFrames || []) : (res.sortFrames || []));
    setFrameIdx(0);
    setIsPlaying(true);
  };

  const handleReset = () => {
    setIsPlaying(false);
    setFrameIdx(0);
    setFrames([]);
  };

  return (
    <div className="flex flex-col gap-4">
      <div className="relative bg-sky-200/50 rounded-3xl p-4 border-4 border-navy/10 overflow-hidden shadow-inner flex items-center justify-center min-h-[300px]">
        {board.kind === "grid" ? (
          <GridView board={board} frame={frames[frameIdx] as GridFrame} />
        ) : (
          <SortView board={board} frames={frames as SortFrame[]} currentIdx={frameIdx} />
        )}
      </div>

      <div className="flex gap-2 justify-center">
        {!isPlaying && frames.length === 0 ? (
          <button onClick={handlePlay} className="btn-primary flex-1 max-w-[200px]">▶️ Jalankan</button>
        ) : (
          <button onClick={handleReset} className="btn-ghost flex-1 max-w-[200px]">🔄 Ulangi</button>
        )}
      </div>
    </div>
  );
}

function GridView({ board, frame }: { board: GridBoard, frame?: GridFrame }) {
  const f = frame || { pos: board.start, collected: [], counter: 0 };
  return (
    <div 
      className="grid gap-1 bg-white p-2 rounded-2xl shadow-sm"
      style={{ gridTemplateColumns: `repeat(${board.width}, 3rem)`, gridTemplateRows: `repeat(${board.height}, 3rem)` }}
    >
      {/* Cells */}
      {Array.from({ length: board.height * board.width }).map((_, i) => {
        const x = i % board.width;
        const y = Math.floor(i / board.width);
        const isGoal = board.goal.x === x && board.goal.y === y;
        const isWall = board.walls.find(w => w.x === x && w.y === y);
        const itemIdx = board.items.findIndex(it => it.x === x && it.y === y);
        const item = itemIdx >= 0 ? board.items[itemIdx] : null;
        const isCollected = item !== null && f.collected.includes(itemIdx);

        return (
          <div key={i} className={`relative flex items-center justify-center rounded-xl text-3xl ${isWall ? 'bg-navy/5' : 'bg-peach-200/50 border-2 border-peach-300'}`}>
            {isGoal && <span className="absolute opacity-50 z-0">{board.goal.emoji}</span>}
            {isWall && <span className="z-10">{isWall.emoji || "🧱"}</span>}
            {item && !isCollected && <span className="z-10">{item.emoji}</span>}

            {/* Player Character */}
            {f.pos.x === x && f.pos.y === y && (
              <span className={`absolute z-20 transition-transform duration-500 text-4xl ${f.event === 'bump' || f.event === 'wrong-order' ? 'animate-shake' : ''} ${f.event === 'goal' ? 'animate-bounce-soft' : ''}`}>
                🦊
              </span>
            )}
          </div>
        );
      })}
    </div>
  );
}

function SortView({ board, frames, currentIdx }: { board: SortBoard, frames: SortFrame[], currentIdx: number }) {
  // Simple visualization for sort board: show items at top, moving into boxes at bottom
  return (
    <div className="flex flex-col h-full w-full justify-between items-center gap-8 py-4">
      {/* Items queue */}
      <div className="flex gap-2 bg-white/50 p-3 rounded-full overflow-x-auto max-w-full">
        {board.items.map((item, i) => {
          const frame = frames.find(f => f.itemIndex === i);
          const isProcessing = currentIdx >= frames.findIndex(f => f.itemIndex === i) && frame === undefined; // approximate logic for demo
          const isDone = frame !== undefined && frames.indexOf(frame) <= currentIdx;
          return (
             <div key={i} className={`text-4xl transition-all duration-300 ${isDone ? 'scale-0 opacity-0 w-0' : 'scale-100 opacity-100'} ${isProcessing ? 'animate-bounce-soft' : ''}`}>
               {item.emoji}
             </div>
          );
        })}
      </div>

      {/* Boxes */}
      <div className="flex gap-4 w-full justify-center">
        {board.boxes.map(box => {
          // Find if the currently processed item is dropped here
          const currentFrame = frames[currentIdx];
          const isDroppedHere = currentFrame?.box === box.id;

          return (
            <div key={box.id} className={`flex flex-col items-center gap-2 p-4 rounded-2xl border-4 transition-colors ${isDroppedHere ? (currentFrame.correct ? 'bg-leaf/20 border-leaf' : 'bg-berry/20 border-berry animate-shake') : 'bg-white border-navy/10'}`}>
               <span className="text-4xl">{box.emoji}</span>
               <span className="font-bold text-navy text-sm text-center max-w-[100px] leading-tight">{box.label}</span>
               {/* Show accumulated items */}
               <div className="flex flex-wrap gap-1 mt-2 justify-center max-w-[120px]">
                 {frames.slice(0, currentIdx + 1).filter(f => f.box === box.id).map(f => (
                    <span key={f.itemIndex} className="text-xl">{board.items[f.itemIndex].emoji}</span>
                 ))}
               </div>
            </div>
          )
        })}
      </div>
    </div>
  );
}

"use client";
import type { Block, BlockType, PaletteItem } from "@/lib/missions/types";
import { useState } from "react";
import { fromPalette, moveBlock, nudgeBlock, removeBlock, updateBlock } from "@/lib/missions/program";

// Simple native HTML5 D&D based block editor for React 19 MVP

export function BlockEditor({
  program,
  onChange,
  palette,
}: {
  program: Block[];
  onChange: (prog: Block[]) => void;
  palette: PaletteItem[];
}) {
  const [draggedBlock, setDraggedBlock] = useState<string | null>(null);

  const handleDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData("text/plain", id);
    setDraggedBlock(id);
    e.stopPropagation();
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault(); // Necessary to allow dropping
    e.dataTransfer.dropEffect = "move";
  };

  const handleDrop = (e: React.DragEvent, targetContainer: string, index: number) => {
    e.preventDefault();
    e.stopPropagation();
    const id = e.dataTransfer.getData("text/plain");
    if (!id) return;
    setDraggedBlock(null);
    onChange(moveBlock(program, id, targetContainer, index));
  };

  const handleAddPalette = (item: PaletteItem) => {
    onChange([...program, fromPalette(item)]);
  };

  return (
    <div className="flex flex-col h-full gap-4 relative">
      {/* Workspace */}
      <div 
        className="flex-1 bg-peach/30 border-2 border-navy/10 rounded-2xl p-4 overflow-y-auto flex flex-col gap-2 min-h-[300px]"
        onDragOver={handleDragOver}
        onDrop={(e) => handleDrop(e, "root", program.length)}
      >
        {program.length === 0 ? (
          <div className="m-auto text-center text-navy-300 font-bold max-w-[200px]">
            Tarik blok dari bawah atau sentuh blok untuk menambahkan ke sini.
          </div>
        ) : (
          <BlockList 
            blocks={program} 
            containerKey="root" 
            program={program} 
            onChange={onChange}
            draggedBlock={draggedBlock}
            onDragStart={handleDragStart}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
          />
        )}
      </div>

      {/* Palette */}
      <div className="bg-white rounded-2xl border-2 border-navy/10 p-4 shadow-sm">
        <h3 className="text-sm font-bold text-navy-300 mb-3 uppercase tracking-wider">Blok Tersedia</h3>
        <div className="flex flex-wrap gap-2">
          {palette.map((item, i) => (
            <button
              key={i}
              onClick={() => handleAddPalette(item)}
              className="px-4 py-2 rounded-xl text-white font-bold shadow-pop-sm transition-transform active:translate-y-1 bg-sky hover:bg-sky-700"
            >
              {item.type === "move" && `Gerak ${item.dir === "up" ? "Atas" : item.dir === "down" ? "Bawah" : item.dir === "left" ? "Kiri" : "Kanan"}`}
              {item.type === "repeat" && "Ulangi"}
              {item.type === "if" && "Jika..."}
              {item.type === "put" && "Masukkan"}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

function BlockList({ blocks, containerKey, program, onChange, draggedBlock, onDragStart, onDrop, onDragOver }: any) {
  return (
    <>
      {blocks.map((b: Block, i: number) => (
        <div key={b.id} className="relative group">
          {/* Drop indicator above */}
          <div className="h-2 w-full transition-colors opacity-0 group-hover:opacity-100 hover:bg-sky/50 rounded-full" onDragOver={onDragOver} onDrop={(e) => onDrop(e, containerKey, i)} />

          <div 
            draggable
            onDragStart={(e) => onDragStart(e, b.id)}
            className={`p-3 rounded-xl border-2 border-b-4 border-navy/20 cursor-grab active:cursor-grabbing text-white font-bold flex flex-col gap-2 transition-opacity ${draggedBlock === b.id ? 'opacity-30' : 'opacity-100'} ${getBlockColor(b.type)}`}
          >
            <div className="flex justify-between items-center gap-2">
               <span className="flex-1">{getBlockLabel(b)}</span>

               {/* Controls */}
               <div className="flex gap-1 bg-white/20 rounded-lg p-1">
                 <button onClick={() => onChange(nudgeBlock(program, b.id, -1))} className="w-6 h-6 hover:bg-white/30 rounded">⬆️</button>
                 <button onClick={() => onChange(nudgeBlock(program, b.id, 1))} className="w-6 h-6 hover:bg-white/30 rounded">⬇️</button>
                 <button onClick={() => onChange(removeBlock(program, b.id))} className="w-6 h-6 hover:bg-berry/80 hover:text-white rounded ml-1 text-berry bg-white">❌</button>
               </div>
            </div>

            {/* Nested blocks */}
            {b.type === "repeat" && (
               <div className="ml-4 pl-4 border-l-4 border-white/30 min-h-[40px] flex flex-col gap-2" onDragOver={onDragOver} onDrop={(e) => onDrop(e, `${b.id}:body`, b.body.length)}>
                 <BlockList blocks={b.body} containerKey={`${b.id}:body`} program={program} onChange={onChange} draggedBlock={draggedBlock} onDragStart={onDragStart} onDrop={onDrop} onDragOver={onDragOver} />
               </div>
            )}

            {b.type === "if" && (
               <div className="ml-4 flex flex-col gap-2">
                 <div className="text-sm opacity-90 mt-1">MAKA:</div>
                 <div className="pl-4 border-l-4 border-white/30 min-h-[40px] flex flex-col gap-2" onDragOver={onDragOver} onDrop={(e) => onDrop(e, `${b.id}:then`, b.then.length)}>
                   <BlockList blocks={b.then} containerKey={`${b.id}:then`} program={program} onChange={onChange} draggedBlock={draggedBlock} onDragStart={onDragStart} onDrop={onDrop} onDragOver={onDragOver} />
                 </div>
                 <div className="text-sm opacity-90 mt-1">JIKA TIDAK:</div>
                 <div className="pl-4 border-l-4 border-white/30 min-h-[40px] flex flex-col gap-2" onDragOver={onDragOver} onDrop={(e) => onDrop(e, `${b.id}:else`, b.else.length)}>
                   <BlockList blocks={b.else} containerKey={`${b.id}:else`} program={program} onChange={onChange} draggedBlock={draggedBlock} onDragStart={onDragStart} onDrop={onDrop} onDragOver={onDragOver} />
                 </div>
               </div>
            )}
          </div>
        </div>
      ))}

      {/* Drop indicator at bottom */}
      <div className="h-8 w-full border-2 border-dashed border-transparent hover:border-sky/50 rounded-xl" onDragOver={onDragOver} onDrop={(e) => onDrop(e, containerKey, blocks.length)} />
    </>
  );
}

function getBlockColor(type: BlockType) {
  switch (type) {
    case "move": return "bg-orange hover:bg-orange-600";
    case "repeat": return "bg-leaf hover:bg-leaf-700";
    case "if": return "bg-sky hover:bg-sky-700";
    case "put": return "bg-sun hover:bg-yellow-500 text-navy";
  }
}

function getBlockLabel(b: Block) {
  if (b.type === "move") return `Gerak ${b.dir === "up" ? "Atas ⬆️" : b.dir === "down" ? "Bawah ⬇️" : b.dir === "left" ? "Kiri ⬅️" : "Kanan ➡️"}`;
  if (b.type === "repeat") return `Ulangi ${b.times}x`;
  if (b.type === "if") return `Jika ${b.cond}`;
  if (b.type === "put") return `Masukkan ke ${b.box}`;
  return "";
}

"use client";
import { useState } from "react";
import type { Mission, Block, RunResult } from "@/lib/missions/types";
import { BlockEditor } from "@/components/mission/BlockEditor";
import { BoardView } from "@/components/mission/BoardView";
import { BibiMascot } from "@/components/brand/BibiMascot";
import { feedbackFor } from "@/lib/missions/engine";
import Link from "next/link";
import { useRouter } from "next/navigation";

// The interactive mission workspace

export default function MissionWorkspace({ 
  mission, 
  childId,
  starsToUnlock,
}: { 
  mission: Mission; 
  childId: string;
  starsToUnlock: number;
}) {
  const router = useRouter();
  const [program, setProgram] = useState<Block[]>([]);
  const [result, setResult] = useState<RunResult | null>(null);
  const [attempts, setAttempts] = useState(0);
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleResult = async (res: RunResult) => {
    setResult(res);
    setAttempts(a => a + 1);

    // Save attempt (and progress if success) to server via API
    try {
      setIsSubmitting(true);
      const data = new FormData();
      data.append("missionId", mission.id);
      data.append("success", String(res.success));
      data.append("blocksUsed", String(res.blocksUsed));
      data.append("hintsUsed", "0"); // TODO: integrate with Bibi chat

      const response = await fetch("/api/progress", {
        method: "POST",
        body: data,
      });
      if (res.success && response.ok) {
        // We will show a success modal, then route back to map
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="flex flex-col h-dvh bg-peach overflow-hidden">
      {/* Top Bar */}
      <header className="bg-white px-4 py-3 border-b-2 border-navy/10 flex justify-between items-center z-10 shadow-sm shrink-0">
        <Link href="/peta" className="btn-ghost !min-h-10 px-4 py-2 text-sm">⬅️ Peta</Link>
        <h1 className="font-display font-bold text-navy text-xl text-center flex-1 mx-4 truncate">
          Misi {mission.order}: {mission.title}
        </h1>
        <div className="flex gap-2">
          {/* Stars indicator */}
          <div className="bg-peach-200 text-orange-700 font-bold px-3 py-1.5 rounded-full flex gap-1 items-center">
             ⭐ <span className="hidden sm:inline">Terkumpul</span>
          </div>
        </div>
      </header>

      {/* Main Workspace (split layout on desktop, stacked on mobile) */}
      <main className="flex-1 flex flex-col md:flex-row overflow-hidden relative">

        {/* Left: Board & Story */}
        <section className="w-full md:w-5/12 lg:w-1/2 flex flex-col border-b-2 md:border-b-0 md:border-r-2 border-navy/10 bg-white">
           <div className="p-4 md:p-6 bg-peach-200/30 text-navy text-lg leading-relaxed flex items-start gap-4">
              <BibiMascot className="w-16 h-16 shrink-0" mood={result?.success ? "cheer" : "happy"} />
              <div>
                <p className="font-bold">{mission.story}</p>
                <p className="text-sm mt-1 bg-white/60 inline-block px-2 py-1 rounded-lg text-navy-700 font-bold">🎯 Tujuan: {mission.goal}</p>
              </div>
           </div>

           <div className="flex-1 p-4 md:p-6 overflow-y-auto">
             <BoardView board={mission.board} program={program} onResult={handleResult} />

             {/* Feedback Area */}
             {result && (
               <div className={`mt-6 p-4 rounded-2xl border-2 animate-pop-in ${result.success ? 'bg-leaf/10 border-leaf text-leaf-700' : 'bg-orange/10 border-orange text-orange-700'}`}>
                 <p className="font-bold text-lg">{feedbackFor(result)}</p>
                 {!result.success && (
                   <button className="btn-ghost w-full mt-3 flex items-center justify-center gap-2">
                     Tanya Bibi <BibiMascot className="w-6 h-6" mood="thinking" />
                   </button>
                 )}
               </div>
             )}
           </div>
        </section>

        {/* Right: Block Editor */}
        <section className="w-full md:w-7/12 lg:w-1/2 flex flex-col bg-peach/10 p-4">
           <BlockEditor 
             program={program} 
             onChange={setProgram} 
             palette={mission.palette} 
           />
        </section>

